def add(name,*groups):
 facts=[]
 for ref,statements in groups:
  for s in statements.split('||'):
   facts.append({'id':f'f{len(facts)+1}','statement':s.strip(),'source_refs':ref.split('|')})
 E['python.'+name]=facts
